import {Renderer,pose,mul,transform,V,assetFetch} from './engine.js';
import {CATEGORIES,COLORS,DAY_NAMES,TASK_NAMES,makeBook,dayConfig,newProgress,complete,addProgress,canShelve,blocked,pathfind,transferBook} from './core.js';
import {LibraryAudio} from './audio.js';
import {SERVICE_LIMIT,MAX_INQUIRIES,SHIFT_SECONDS,CHANNELS,SERVICE_POLICY,PHONE_TOPICS,deskLimit,unresolved,activeRequests,secondsLeft,initServiceDay,activateRequest,advanceArrivals,resolveRequest,failRequest,expireRequests,deliverComplaints,closeServiceDay,shuffle} from './service.js';
import {KDC_SECTIONS,sectionName,sectionOptions,EVENTS} from './kdc.js';
const $=id=>document.getElementById(id),canvas=$('scene'),modal=$('modal'),SAVE='little-library-v2',audio=new LibraryAudio();
let renderer,assets,layout,state,keys=new Set(),paused=false,selected=null,clock=0,lastTime=0,saveTimer=0,toastTimer=0,nearby=null,modalNpc=null,modalContext='none',uiTimer=0,targetPath=[],drag=null,trail=[],follow=false,cameraAngle=.68,zoom=26,cameraTarget=[0,.3,0],userStarted=false;
const dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function say(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=3.8}
function open(title,body,actions=[],type='작은 도서관',context='work'){keys.clear();targetPath=[];modalContext=context;if(context!=='service')modalNpc=null;$('close-modal').hidden=['morning','review'].includes(context)||(context==='help'&&!userStarted);$('modal-title').textContent=title;$('modal-type').textContent=type;$('modal-body').innerHTML=body;$('modal-actions').replaceChildren();for(let a of actions){let b=document.createElement('button');b.textContent=a.label;if(a.primary)b.className='primary';b.disabled=!!a.disabled;b.onclick=a.run;$('modal-actions').append(b)}if(!modal.open)modal.showModal()}
function close(){modal.close();modalNpc=null;modalContext='none';canvas.focus({preventScroll:true})}
function bookHtml(b){return `<div class="dialog-book"><strong>${escape(b.title)}</strong><br>청구번호 ${b.code} · ${b.section} ${sectionName(b.section)} · ${CATEGORIES[b.category]}</div>`}
function newState(){return {version:2,day:1,score:0,rng:122,player:{x:-3.4,z:7.2,angle:0,walk:0},cart:{x:4.9,z:6.3,angle:0,attached:false,books:[]},hands:[],machine:[],floor:[],npcs:[],progress:newProgress(),shelved:[],display:[],ticket:null,ended:false,fired:false,elapsed:0,complaints:[],nationalDays:[],reviews:[],inbox:[]}}
function populateDay(){let d=state.day;state.progress=newProgress();initServiceDay(state);state.mailChecked=false;state.ticket=null;state.hands=[];state.cart={x:4.9,z:6.3,angle:0,attached:false,books:[]};state.player={x:-3.4,z:7.2,angle:0,walk:0};targetPath=[];trail=[];state.shelved=[];state.display=[];
 let count=dayConfig(d).collected,locations=[{x:-2.5,z:2.2},{x:5.4,z:-3},{x:-6.9,z:-7.5}];state.floor=locations.slice(0,count).map((p,i)=>({...makeBook(`d${d}-floor${i}`,((d*2+i*3)%10)),...p}));
 state.cart.books=[makeBook(`d${d}-cart0`,(d+1)%10),makeBook(`d${d}-cart1`,(d+4)%10)];
 state.machine=Array.from({length:d+1},(_,i)=>makeBook(`d${d}-machine${i}`,(d+i+6)%10));
 selected=state.cart.books[0]?.id||null;save();renderUI()
}
function safeLoad(){try{let s=JSON.parse(localStorage.getItem(SAVE));if(!s||s.version!==2||s.day<1||s.day>5||!s.player||!s.progress||!Array.isArray(s.npcs)||!Array.isArray(s.complaints))return false;state=s;state.cart.attached=false;state.npcs.forEach(n=>{n.path=[]});selected=state.hands[0]?.id||state.cart.books[0]?.id;return true}catch{return false}}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));$('save-status').textContent='진행 상황 자동 저장'}catch{$('save-status').textContent='저장 불가 · 브라우저 저장 공간 확인'}}
function carrying(){return [...state.hands,...(dist(state.player,state.cart)<2.4?state.cart.books:[])]}
function getSelected(){let list=carrying();return list.find(b=>b.id===selected)||list[0]}
function removeBook(id){for(let list of [state.hands,state.cart.books]){let i=list.findIndex(b=>b.id===id);if(i>=0)return list.splice(i,1)[0]}return null}
function actionDone(key,message){addProgress(state,key);save();renderUI();if(message)say(message)}
function renderUI(){let goal=dayConfig(state.day),p=state.progress;$('day-label').textContent=`DAY ${String(state.day).padStart(2,'0')} / 05`;$('day-title').textContent=DAY_NAMES[state.day-1];$('score').textContent=`${state.score}점`;
 let ratio=Object.keys(goal).reduce((s,k)=>s+Math.min(1,p[k]/goal[k]),0)/Object.keys(goal).length;$('progress').style.width=ratio*100+'%';$('tasks').innerHTML=Object.entries(goal).map(([k,v])=>`<div class="task ${p[k]>=v?'done':''}"><span class="task-icon">${p[k]>=v?'✓':'·'}</span><span>${TASK_NAMES[k]}</span><span class="task-count">${Math.min(v,p[k])} / ${v}</span></div>`).join('');
 let visible=state.npcs.filter(n=>n.status!=='gone'),active=activeRequests(state);$('visitor-count').textContent=`문의 ${active.length} / ${MAX_INQUIRIES}`;$('visitors').innerHTML=visible.map(n=>{let left=secondsLeft(state,n),timed=unresolved(n)&&n.deadline!=null;return `<div class="visitor-row ${timed?'waiting':''} ${timed&&left<10?'urgent':''}"><span class="visitor-dot"></span><span>${escape(n.name)} · ${n.mode==='phone'?'☎ 전화':n.kind==='roam'?'열람 중':n.status==='leaving'?n.dissatisfied?'불만 퇴실':'퇴실 중':n.mode==='kiosk'?'기기 오류':n.kind==='question'?'문의':n.kind==='loan'?'대출':n.kind==='return'?'반납':'프린터 문의'}</span><small>${timed?Math.ceil(left)+'초':unresolved(n)?'다가오는 중':''}</small></div>`}).join('');
 let remaining=Math.max(0,SHIFT_SECONDS-state.elapsed);$('shift-clock').textContent=`퇴근까지 ${Math.floor(remaining/60)}:${String(Math.floor(remaining%60)).padStart(2,'0')}`;$('complaint-count').textContent=`국민신문고 ${state.nationalDays.length} / 3일`;$('queue-limit').textContent=`데스크 최대 ${deskLimit(state.day)}명 · 민원 ${state.failures.length}건 예정`;
 let call=active.find(n=>n.mode==='phone');$('phone-btn').textContent=call?`☎ ${Math.ceil(secondsLeft(state,call))}초 · 전화 응대`:'☎ 데스크 전화';$('phone-btn').classList.toggle('ringing',!!call&&!call.answered);
 $('finish-day').disabled=state.elapsed<60||state.ended||state.morningPending;$('finish-day').textContent=state.ended?state.fired?'해고 · 근무 종료':'5일 근무 완료':state.shiftClosed?'하루 리뷰 다시 보기':remaining<=0?'퇴근 리뷰 보기':'오늘의 업무 마치기';$('carry-info').textContent=`손에 ${state.hands.length} / 3권`;
 let list=carrying(),sel=getSelected();$('inventory').replaceChildren();for(let b of list){let el=document.createElement('button');el.className='book-slot'+(b.id===sel?.id?' selected':'');el.innerHTML=`<span class="book-spine" style="background:${COLORS[b.category]}">${b.code}</span><span class="book-title">${escape(b.title)}<small>${b.code} ${CATEGORIES[b.category]} · ${state.hands.includes(b)?'손':'카트'}</small></span>`;el.title='클릭하면 선택, I로 책 관리';el.onclick=()=>{selected=b.id;renderUI()};$('inventory').append(el)}for(let i=list.length;i<3;i++){let el=document.createElement('div');el.className='empty-slot';el.textContent='+';$('inventory').append(el)}
 $('cart-label').textContent=`북카트 · ${state.cart.attached?'연결됨':'분리됨'}`;$('cart-info').textContent=`${state.cart.books.length} / 12권 · ${state.cart.attached?'C로 놓기':'가까이에서 E로 연결'}`;
 $('day-tip').textContent=active.length?'문의는 30초 안에 해결하세요. 응대 창에서도 시간은 흐릅니다. 책은 도망가지 않지만 민원은 내일 돌아옵니다.':'책 청구번호에 맞춰 정리하세요. 전화·문의는 10–30초 간격으로 옵니다. 운영 규정은 데스크 컴퓨터에서 확인할 수 있어요.';
}
function nearest(){let p=state.player,candidates=[];const add=(type,obj,d,label)=>{if(d< (type==='shelf'?2.25:type==='desk'?2.55:1.9))candidates.push({type,obj,d,label})};
 for(let b of state.floor)add('book',b,dist(p,b),`책 줍기 · ${b.title}`);
 for(let n of state.npcs)if(n.mode!=='phone'&&unresolved(n)&&['waiting','asking'].includes(n.status))add('npc',n,dist(p,n),`${n.name} · ${n.mode==='kiosk'?'대출반납기 오류 해결':n.kind==='question'?'문의 듣기':n.kind==='loan'?'대출 처리':n.kind==='return'?'반납 처리':'문제 접수'}`);
 if(activeRequests(state).some(n=>n.mode==='phone')&&dist(p,layout.phone)<2.3)add('phone',layout.phone,.05,'☎ 전화 받기 · 30초 제한');
 for(let s of layout.shelves){let d=Math.hypot(Math.max(Math.abs(p.x-s.x)-1.4,0),Math.max(Math.abs(p.z-s.z)-.5,0));add('shelf',s,d,`${s.code} ${CATEGORIES[s.category]} · 책 정리`)}
 add('cart',state.cart,dist(p,state.cart),'북카트 · '+(state.cart.attached?'놓기 / 책 관리':'연결 / 책 관리'));
 add('machine',layout.return,Math.hypot(Math.max(Math.abs(p.x-layout.return.x)-.9,0),Math.max(Math.abs(p.z-layout.return.z)-.75,0)),`반납기 · ${state.machine.length}권 수거`);
 add('desk',layout.desk,Math.hypot(Math.max(Math.abs(p.x-layout.desk.x)-2.2,0),Math.max(Math.abs(p.z-layout.desk.z)-.95,0)),'데스크 컴퓨터 · 도서 검색 / 업무');
 add('exhibition',layout.exhibition,Math.hypot(Math.max(Math.abs(p.x+8)-1.5,0),Math.max(Math.abs(p.z-3.3)-.65,0)),'전시 공간 · 책 배치');
 add('kiosk',layout.kiosk,dist(p,layout.kiosk),'무인 대출반납기 · 상태 확인');
 add('board',layout.board,dist(p,layout.board),'벽면 게시판 · 운영시간 / 행사 안내');
 candidates.sort((a,b)=>a.d-b.d);return candidates[0]||null
}
function interact(){if(paused||state.ended||modal.open)return;if(!nearby){say('책, 서가, 이용자 또는 기기 가까이에서 E를 눌러 주세요.');return}let {type,obj}=nearby;
 if(type==='book'){let dest=state.cart.attached&&dist(state.cart,obj)<2.7&&state.cart.books.length<12?state.cart.books:state.hands;if(dest.length>=(dest===state.hands?3:12)){say('손이 가득 찼어요. 카트에 책을 담아 주세요.');return}state.floor=state.floor.filter(b=>b.id!==obj.id);dest.push(obj);selected=obj.id;actionDone('collected',`${obj.title}을 ${dest===state.hands?'손에 들었어요':'카트에 담았어요'}.`)}
 else if(type==='shelf'){if(guideShelfMenu(obj))return;let b=getSelected();if(!b){say('정리할 책이 없어요. 책을 줍거나 북카트를 가까이 가져오세요.');return}if(!canShelve(b,obj.category)){say(`${b.title}은 ${b.code} · ${b.section} ${sectionName(b.section)} 구역의 책이에요.`);return}removeBook(b.id);state.shelved.push({...b,x:obj.x,z:obj.z});state.shelved.sort((a,b)=>Number(a.code)-Number(b.code));actionDone('shelved',`${obj.code} 서가의 ${b.section} ${sectionName(b.section)} 구역에 ${b.code} 책을 정리했어요.`)}
 else if(type==='cart')cartMenu();else if(type==='machine')machineMenu();else if(type==='desk')computerMenu();else if(type==='exhibition')exhibitionMenu();else if(type==='npc')talk(obj);else if(type==='phone')phoneMenu();else if(type==='kiosk')kioskMenu();else if(type==='board')noticeBoardMenu()
}
function toggleCart(){if(state.cart.attached){state.cart.attached=false;trail=[];say('북카트를 놓았어요. 책은 그대로 실려 있어요.')}else{if(dist(state.player,state.cart)>1.9){say('북카트 가까이에서 연결할 수 있어요.');return}state.cart.attached=true;trail=[{x:state.cart.x,z:state.cart.z},{x:state.player.x,z:state.player.z}];say('북카트를 연결했어요. 이동하면 책과 함께 따라옵니다.')}save();renderUI()}
function cartMenu(){open('북카트',`책 ${state.cart.books.length} / 12권이 담겨 있어요. 가까운 카트의 책은 서가 앞에서 바로 정리할 수 있어요.`,[{label:state.cart.attached?'카트 놓기':'카트 연결하기',primary:true,run:()=>{close();toggleCart()}},{label:'손에 든 책을 모두 카트에 담기',disabled:!state.hands.length||state.cart.books.length>=12,run:()=>{while(state.hands.length&&state.cart.books.length<12)transferBook(state.hands,state.cart.books,state.hands[0].id,12);save();renderUI();cartMenu()}},{label:'책 목록 관리',run:inventoryMenu},{label:'닫기',run:close}],'북카트')}
function inventoryMenu(){let list=carrying();open('책 목록',list.length?list.map(bookHtml).join(''):'가지고 있는 책이 없어요.',[...list.map(b=>({label:`${b.code} · ${b.title} ${state.hands.includes(b)?'→ 카트에 담기':'→ 손에 들기'}`,disabled:dist(state.player,state.cart)>2.4||(state.hands.includes(b)?state.cart.books.length>=12:state.hands.length>=3),run:()=>{if(state.hands.includes(b))transferBook(state.hands,state.cart.books,b.id,12);else transferBook(state.cart.books,state.hands,b.id,3);selected=b.id;save();renderUI();inventoryMenu()}})),{label:'닫기',run:close}],'책 관리')}
function machineMenu(){let jam=state.ticket?.location==='machine';open('무인 반납기',jam?'접수된 문제: 반납 슬롯에 종이가 끼었어요. 잠시 기기를 정지하고 종이를 제거해 주세요.':`반납된 책 ${state.machine.length}권을 수거할 수 있어요. 책 정리를 위해 북카트에 옮겨 주세요.`,[...(jam?[{label:'기기 정지 → 끼인 종이 제거 → 재시작',primary:true,run:()=>{state.ticket=null;close();actionDone('fixed','반납기가 정상 작동해요. 문제를 해결했어요.')}}]:[]),{label:state.cart.attached?'반납 도서 → 북카트에 수거':'반납 도서 → 손에 수거',disabled:!state.machine.length||!!jam,primary:!jam,run:()=>{let dest=state.cart.attached&&dist(state.player,state.cart)<2.4?state.cart.books:state.hands,cap=dest===state.hands?3:12;if(dest.length>=cap){say('책을 담을 공간이 부족해요. 먼저 서가에 정리해 주세요.');return}let count=0;while(state.machine.length&&dest.length<cap){dest.push(state.machine.shift());count++}selected=dest.at(-1)?.id;save();renderUI();close();say(`반납 도서 ${count}권을 수거했어요.`)}},{label:'닫기',run:close}],'반납 업무')}
function exhibitionMenu(){let b=getSelected();open('이달의 책 전시',`좋은 책을 골라 전시해 주세요.${b?bookHtml(b):'<p>책을 들고 오거나 북카트를 가까이 가져와 주세요.</p>'}`, [{label:'선택한 책 전시하기',disabled:!b||state.display.length>=4,primary:true,run:()=>{removeBook(b.id);state.display.push(b);close();actionDone('displayed',`${b.title}을 전시했어요.`)}},{label:'닫기',run:close}],'전시 공간')}
function computerMenu(){let queue=state.npcs.filter(n=>unresolved(n)&&n.status==='waiting'&&n.mode==='desk');open('사서 데스크 컴퓨터',`<p>도서 검색 · 대출/반납 · 이용자 지원</p><p>대기 ${queue.length}명 / 최대 ${deskLimit(state.day)}명<br>화면을 보고 있어도 문의 시간은 계속 흐릅니다.</p>`,[...queue.map(n=>({label:`${n.name} · ${n.subject} (${Math.ceil(secondsLeft(state,n))}초)`,primary:true,run:()=>talk(n)})),{label:'☎ 데스크 전화 확인',run:phoneMenu},{label:'도서 검색 · 분류표 확인',run:()=>open('도서 검색',KDC_SECTIONS.map((sections,i)=>`<h3>${String(i*100).padStart(3,'0')} ${CATEGORIES[i]}</h3>`+sections.map(([code,name])=>`<div class="catalog-row"><span>${code} · ${name}</span><span>${i<5?'뒤쪽':'앞쪽'} ${i%5+1}번째 서가</span></div>`).join('')).join(''),[{label:'컴퓨터로 돌아가기',run:computerMenu}],'청구번호 안내')},{label:'도서관 운영 규정 확인',run:()=>policyMenu(computerMenu)},{label:'받은 민원 다시 보기',run:()=>open('받은 민원함',complaintHtml(state.inbox),[{label:'컴퓨터로 돌아가기',run:computerMenu}],'민원 보관함')},{label:'닫기',run:close}],'사서 업무')}
function policyMenu(back=computerMenu){open('작은 도서관 운영 규정',SERVICE_POLICY.map(([k,v])=>`<div class="policy-row"><strong>${escape(k)}</strong><span>${escape(v)}</span></div>`).join('')+'<p>게임 속 도서관의 운영 규정입니다. 응대 중 확인해도 시간은 흐릅니다.</p>',[{label:'돌아가기',run:back}],'응대 매뉴얼')}
function served(n,key,message){if(!resolveRequest(state,n))return;if(n.mode!=='phone')n.path=pathfind(n,{x:0,z:10},layout.colliders);close();audio.success();actionDone(key,message)}
function reject(n,reason,answer=''){let c=failRequest(state,n,reason,answer);if(!c)return;if(n.mode!=='phone')n.path=pathfind(n,{x:0,z:10},layout.colliders);close();audio.failure();save();renderUI();say(`${n.name}: “${reason==='timeout'?'계속 기다리기만 하네요!':'이런 응대는 처음이네요!'}” 불만 기록 · 내일 민원 예정`)}
function respond(n,label,outcome){if(!unresolved(n)){close();say('이미 끝난 문의예요.');return}if(secondsLeft(state,n)<=0){reject(n,'timeout');return}n.lastAction=label;if(outcome!=='correct'){reject(n,outcome,label);return}if(n.kind==='return')state.machine.push(n.book);if(n.mode==='kiosk')addProgress(state,'transactions');served(n,n.kind==='loan'||n.kind==='return'?'transactions':n.kind==='issue'?'fixed':'questions',`${n.name}의 ${n.subject}을 해결했어요. 민원 씨앗 하나를 치웠습니다.`)}
function talk(n){if(!unresolved(n)||state.shiftClosed||state.ended)return;activateRequest(state,n);modalNpc=n.id;let body,answers;
 if(n.mode!=='phone'&&n.kind==='question'){open(`${n.name}의 책 문의`,`<div class="service-deadline">안내 완료까지 <strong id="service-timer">${Math.ceil(secondsLeft(state,n))}초</strong></div>“${escape(n.guide.subject)} 책을 찾고 싶은데 어디로 가야 하나요?”<p>수락하면 이용자가 따라옵니다. 해당 서가까지 이동해서 E로 세부 분류를 안내하세요.</p>`,[{label:'네, 알겠습니다.',primary:true,run:()=>{n.guiding=true;n.status='guiding';n.lastAction='네, 알겠습니다라고 말하고 서가로 안내 중';close();save();renderUI();say(`${n.name}이 따라옵니다. ${n.guide.subject} 책이 있는 서가에서 E를 눌러 주세요.`)}}],'서가 안내','service');return}
 if(n.mode==='phone'){n.answered=true;n.status='asking';let t=PHONE_TOPICS.find(t=>t.id===n.topic);body=`“${escape(t.question)}”`;answers=t.answers}
 else if(n.kind==='question'){let c=n.category;body=`“${CATEGORIES[c]} 분야의 책은 어디 있어요? 제 발이 서가 검색을 대신하고 있어요.”`;answers=[[`${String(c*100).padStart(3,'0')}번대 ${CATEGORIES[c]} 서가 위치를 친절하게 안내한다.`,'correct'],[`${String(((c+3)%10)*100).padStart(3,'0')}번대 서가라고 대충 말한다.`,'wrong'],['저도 바쁜데 직접 찾으시면 안 돼요?','rude']]}
 else if(n.kind==='loan'){body=`“이 책 빌릴게요. 회원증도 준비했어요.”${bookHtml(n.book)}`;answers=[['회원증 확인 → 책 바코드 스캔 → 대출 등록과 반납 예정일 안내','correct'],['회원 확인 없이 대출 기록을 지우고 그냥 가져가라고 한다.','wrong'],['기계 있잖아요. 제가 꼭 해드려야 합니까?','rude']]}
 else if(n.kind==='return'){body=`“이 책 반납할게요. 제 기억력도 같이 반납하고 싶네요.”${bookHtml(n.book)}`;answers=[['바코드 스캔 → 대출 기록의 반납 완료 확인 → 반납함에 옮기기','correct'],['반납 등록 없이 책만 바닥에 내려놓으라고 한다.','wrong'],['왜 읽은 책을 저한테 가져오세요?','rude']]}
 else if(n.mode==='kiosk'){body='“대출반납기가 회원증을 읽고 멈췄어요. 저랑 기계 중 누가 더 얼어 있는 걸까요?”';answers=[['회원증·책 정보 확인 → 처리 기록 확인 → 기기 재시작 → 대출/반납 결과 안내','correct'],['기계가 멈춰도 처리는 됐겠죠. 그냥 가시라고 한다.','wrong'],['기계한테 물어보세요. 저한테 물으면 기계가 서운해해요.','rude']]}
 else{body='“안내 프린터에서 아무것도 안 나와요. 제 인내심만 출력 중이에요.”';answers=[['프린터 연결 확인 → 대기열 초기화 → 시험 인쇄 후 이용 안내','correct'],['화면에 보이면 인쇄된 거라고 우긴다.','wrong'],['눈으로 외워 가세요. 그게 친환경입니다.','rude']]}
 n.options??=shuffle(state,answers);open(n.mode==='phone'?`☎ ${n.name}의 전화`:`${n.name}의 문의`,`<div class="service-deadline">응대 완료까지 <strong id="service-timer">${Math.ceil(secondsLeft(state,n))}초</strong> <small>시간은 계속 흐릅니다</small></div>${body}`,[...n.options.map(([label,outcome])=>({label,run:()=>respond(n,label,outcome)})),...(n.mode==='phone'?[{label:'운영 규정 확인 (시간 계속 흐름)',run:()=>policyMenu(()=>talk(n))}]:[]),{label:'잠시 기다려 주세요 (시간 계속 흐름)',run:()=>{n.lastAction='잠시 기다려 달라고 하고 응대를 미룸';close()}}],n.mode==='phone'?'전화 응대':'30초 안에 해결','service');save()
}
function phoneMenu(){let n=activeRequests(state).find(n=>n.mode==='phone');if(!n){say('지금은 전화가 없어요. 고요함도 잠깐 대출 가능합니다.');return}if(dist(state.player,layout.phone)>2.3){targetPath=pathfind(state.player,{x:-7.5,z:8.85},layout.colliders);say('데스크 전화로 이동합니다. 가까이서 E 또는 F로 받아 주세요.');return}talk(n)}
function kioskMenu(){let n=activeRequests(state).find(n=>n.mode==='kiosk'&&n.status==='waiting');if(n){talk(n);return}open('무인 대출반납기','회원증 읽기 → 책 바코드 스캔 → 처리 결과 확인 순서로 이용합니다. 지금은 도움이 필요한 이용자가 없습니다.',[{label:'닫기',run:close}],'기기 상태')}
function guideShelfMenu(shelf){let n=state.npcs.find(n=>unresolved(n)&&n.guiding&&dist(n,state.player)<3.2);if(!n)return false;if(shelf.category!==n.category){say('이용자가 찾는 주제의 서가가 아닙니다. 데스크 분류표를 확인하고 다른 서가로 안내하세요.');return true}modalNpc=n.id;let options=shuffle(state,sectionOptions(shelf.category,n.guide.section));open(`${n.name}에게 서가 안내`,`<div class="service-deadline">안내 완료까지 <strong id="service-timer">${Math.ceil(secondsLeft(state,n))}초</strong></div><p>“${escape(n.guide.subject)} 책은 어디를 보면 되나요?”</p><p>현재 서가: ${shelf.code} ${CATEGORIES[shelf.category]}<br>청구번호 앞 세 자리의 세부 분류를 안내해 주세요.</p>`,options.map(code=>({label:`이곳의 ${code} ${sectionName(code)}을 보시면 됩니다.`,run:()=>{if(!unresolved(n)||secondsLeft(state,n)<=0){reject(n,'timeout');return}let correct=shelf.category===n.category&&code===n.guide.section,answer=`${shelf.code} 서가에서 ${code} ${sectionName(code)} 구역으로 안내함`;n.lastAction=answer;if(correct){resolveRequest(state,n);addProgress(state,'questions')}else failRequest(state,n,'shelf-wrong',answer);n.status='searching';n.guiding=false;n.searchCorrect=correct;n.searchUntil=state.elapsed+3;n.angle=Math.PI;n.path=[];close();save();renderUI();say(`${n.name}이 책을 찾는 중입니다…`)}})),'서가 안내 · 세부 분류','service');return true}
function noticeBoardMenu(){open('벽면 안내 게시판','<article class="notice-poster"><h3>도서관 이용 안내</h3><strong>운영시간 09:00–18:00</strong><p>매주 월요일 휴관</p></article>'+EVENTS.map(e=>`<article class="notice-poster"><h3>${escape(e.name)}</h3><p><b>일시</b> ${escape(e.date)}<br><b>장소</b> ${escape(e.place)}<br><b>접수</b> ${escape(e.registration)}<br><b>정원</b> ${e.capacity}명</p></article>`).join(''),[{label:'닫기',run:close}],'운영시간 · 행사 안내')}
function complaintHtml(list){return list.length?list.map(c=>`<article class="complaint-card ${c.channel==='national'?'national':''}"><div class="complaint-tag">${CHANNELS[c.channel]} · ${c.sourceDay}일차 ${escape(c.name)}</div><p class="complaint-opener">${escape(c.opener)}</p><strong>문의: ${escape(c.subject)}</strong><p>플레이어의 대처: ${escape(c.response)}</p><blockquote>“${escape(c.rant)}”</blockquote></article>`).join(''):'<div class="modal-message">접수된 민원이 없습니다. 오늘의 가장 희귀한 평화입니다.</div>'}
function showMorning(){if(!state.mailChecked){deliverComplaints(state,state.day);state.mailChecked=true;save()}if(state.fired){showEnding(true);return}open(`${state.day}일차 아침 · 민원 우편함`,`<p>어제의 응대가 오늘의 우편물이 되었습니다.</p>${complaintHtml(state.inbox)}<div class="modal-message">국민신문고를 받은 날: ${state.nationalDays.length} / 3일<br>하루는 4분. 동시 문의 최대 4건, 데스크 최대 ${deskLimit(state.day)}명.<br>30초 안에 해결하고, 국민신문고가 3일 이상 오면 해고됩니다.</div>`,[{label:state.inbox.length?'민원을 읽었다. 일단 출근한다.':'민원 없는 아침 · 근무 시작',primary:true,run:()=>{state.morningPending=false;close();save();renderUI();say('근무 시작! 책장보다 전화벨이 먼저 일어날지도 몰라요.')}}],'아침 보고','morning')}
function showEnding(fired=false){state.ended=true;state.fired=fired;close();save();renderUI();open(fired?'해고되었습니다 · 사서증 반납':'5일간의 사서 생존 성공','<div class="summary-big">'+state.score+' 점</div>'+ (fired?`<p>국민신문고 민원을 받은 날이 ${state.nationalDays.length}일이 되었습니다.</p><div class="modal-message">“책은 제자리에 꽂혔지만, 당신의 자리는 비었습니다.”<br>북카트가 새 담당자를 기다립니다.</div>`:'<p>5일 동안 살아남았습니다. 책도 민원도 분류할 줄 아는 사서가 되었습니다.</p><div class="modal-message">다음 주 근무표는 아직 보지 않는 편이 좋겠습니다.</div>')+complaintHtml(state.inbox),[{label:'근무 종료',primary:true,run:close}],'최종 근무 평가','review')}
function help(){open('사서 생존 매뉴얼','<div class="help-grid"><span>WASD / 방향키</span><span>사서 이동</span><span>바닥 클릭</span><span>통로 따라 이동</span><span>E / F</span><span>상호작용 / 가까운 데스크 전화 응대</span><span>C / I</span><span>북카트 연결 / 책 관리</span><span>Q / R / 휠</span><span>카메라 회전 / 확대</span><span>P</span><span>응대 창 안에서도 일시정지</span></div><div class="modal-message">문의는 30초 안에 완료하세요. 전화·응대·책 관리 창에서는 시간도 흐릅니다. 도움말·일시정지·아침 보고·리뷰에서는 멈춥니다.<br>이용자나 전화는 10–30초 간격으로 등장합니다. 동시 문의는 최대 4건, 데스크는 1–2일차 2명 / 3–5일차 3명입니다.<br>오답·불친절·방치는 내일 민원이 됩니다. 국민신문고를 3일 이상 받으면 해고됩니다.<br>하루 4분, 1분 이후에는 조기 퇴근도 가능하지만 미해결 문의는 불만으로 남습니다.</div>',[{label:userStarted?'근무로 돌아가기':'사서 생존 시작',primary:true,run:()=>{audio.start();userStarted=true;close();if(state.morningPending)showMorning()}}],'조작 안내 · 시간 정지','help')}
function finishDay(){if(state.ended||state.morningPending||state.elapsed<60)return;let review=closeServiceDay(state);close();save();renderUI();open(`${state.day}일차 퇴근 리뷰 · 책보다 민원`,`<div class="summary-big">${state.score} <small>점</small></div><p>정상 응대 ${review.answered}건 · 불만 ${review.failures.length}건<br>책 정리 ${review.progress.shelved}권 · 대출/반납 ${review.progress.transactions}건 · 문제 해결 ${review.progress.fixed}건</p><p>내일 도착 예정 민원. 형식·불만 사유·진상 멘트는 이미 기록되어 있습니다.</p>${complaintHtml(review.failures)}${!complete(state)?'<div class="modal-message">업무 목표를 모두 채우지는 못했습니다. 서가는 내일도 있지만 민원도 내일 옵니다.</div>':''}`,[{label:state.day===5?'최종 평가 확인':'다음 날 아침으로',primary:true,run:()=>{close();if(state.day===5){deliverComplaints(state,5,true);showEnding(state.fired)}else{state.day++;populateDay();showMorning()}}}],'하루 일과 리뷰 · 시간 정지','review')}
function pause(){paused=!paused;$('pause-btn').textContent=paused?'근무 재개':'일시정지';keys.clear();if(paused)say('일시정지 중이에요. 근무 재개 버튼이나 P를 눌러 주세요.')}
function moveEntity(n,dx,dz,r=.28){let moved=false;if(!blocked(n.x+dx,n.z,layout.colliders,r)){n.x+=dx;moved|=Math.abs(dx)>.0001}if(!blocked(n.x,n.z+dz,layout.colliders,r)){n.z+=dz;moved|=Math.abs(dz)>.0001}if(moved){n.angle=Math.atan2(dx,dz);n.walk+=Math.hypot(dx,dz)*5}return moved}
function followPath(n,dt,speed=1.3){if(!n.path.length)return false;let p=n.path[0],d=dist(n,p);if(d<.13){n.path.shift();return true}let step=Math.min(d,speed*dt);return moveEntity(n,(p.x-n.x)/d*step,(p.z-n.z)/d*step)}
function updateNpcs(dt){let queue=state.npcs.filter(n=>n.mode==='desk'&&unresolved(n)&&!n.guiding);queue.sort((a,b)=>a.arrival-b.arrival);
 for(let n of state.npcs){if(n.arrival>state.elapsed||n.status==='gone')continue;n.routeAt-=dt;n.wait+=dt;
 if(n.mode==='phone')continue;
 if(n.status==='searching'){n.walk+=dt*5;n.angle=Math.PI;if(state.elapsed>=n.searchUntil){n.status='leaving';n.path=pathfind(n,{x:0,z:10.1},layout.colliders);say(n.searchCorrect?`${n.name}: “찾았어요! 고맙습니다.”`:`${n.name}: “여기에는 그런 책이 없네요.” 내일 약한 민원이 예정됩니다.`);if(n.searchCorrect)audio.success();else audio.failure()}continue}
 if(n.status==='leaving'){if(!n.path.length)n.path=pathfind(n,{x:0,z:10.1},layout.colliders);followPath(n,dt,1.6);if(dist(n,{x:0,z:10.1})<.7)n.status='gone';continue}
 if(n.mode==='roam'){if(!n.path.length&&n.routeAt<=0){let spots=[{x:-2.3,z:-7.9},{x:6.7,z:3.8},{x:2.2,z:-3.1},{x:-10.8,z:1.5},{x:0,z:6.5}];let goal=spots[n.roamIndex++%spots.length];n.path=pathfind(n,goal,layout.colliders);n.routeAt=3}followPath(n,dt,.95);continue}
 if(n.guiding){n.status='guiding';if(dist(n,state.player)>1.3){if(n.routeAt<=0){n.path=pathfind(n,state.player,layout.colliders);n.routeAt=.45}followPath(n,dt,3.8)}else{n.path=[];n.angle=state.player.angle}continue}
 if(n.mode==='kiosk'){let goal={x:layout.kiosk.x,z:layout.kiosk.z+1.25};if(dist(n,goal)<.25){n.status='waiting';activateRequest(state,n);n.path=[];n.angle=Math.PI}else{if(n.routeAt<=0){n.path=pathfind(n,goal,layout.colliders);n.routeAt=2}followPath(n,dt,2.1)}continue}
 if(n.mode==='approach'){if(dist(n,state.player)<2.8)activateRequest(state,n);if(dist(n,state.player)<1.45){n.status='asking';n.angle=Math.atan2(state.player.x-n.x,state.player.z-n.z);n.path=[]}else{n.status='walking';if(n.routeAt<=0){n.path=pathfind(n,state.player,layout.colliders);n.routeAt=.8}followPath(n,dt,2.9)}continue}
 let index=queue.indexOf(n),goal={x:-6.0+Math.min(index,2)*1.10,z:9.1};if(dist(n,goal)<.24){n.status='waiting';activateRequest(state,n);n.angle=Math.PI;n.path=[]}else{n.status='walking';if(n.routeAt<=0){n.path=pathfind(n,goal,layout.colliders);n.routeAt=2}followPath(n,dt,2.1)}
 }
}
function updatePlayer(dt){let p=state.player,dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dz=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0),moving=dx||dz;
 if(moving){targetPath=[];let length=Math.hypot(dx,dz),c=Math.cos(cameraAngle),s=Math.sin(cameraAngle),wx=(dx*c+dz*s)/length,wz=(-dx*s+dz*c)/length;dx=wx;dz=wz}
 else if(targetPath.length){let goal=targetPath[0],d=dist(p,goal);if(d<.14){targetPath.shift();return}dx=(goal.x-p.x)/d;dz=(goal.z-p.z)/d;moving=true}
 if(moving){let old={x:p.x,z:p.z},speed=state.cart.attached?2.55:3.5;moveEntity(p,dx*speed*dt,dz*speed*dt);
 if(state.cart.attached){trail.push({x:p.x,z:p.z});let distance=0,target=trail[0];for(let i=trail.length-1;i>0;i--){distance+=dist(trail[i],trail[i-1]);if(distance>=1.35){target=trail[i-1];if(i>1)trail.splice(0,i-1);break}}let d=dist(state.cart,target);if(d>.03){let step=Math.min(d,dt*speed*1.8),cx=(target.x-state.cart.x)/d*step,cz=(target.z-state.cart.z)/d*step;moveEntity(state.cart,cx,cz,.40)}if(dist(p,state.cart)>2.1){p.x=old.x;p.z=old.z;targetPath=[];if(clock-saveTimer>1)say('카트가 걸렸어요. 뒤로 조금 움직이거나 C로 놓고 방향을 바꿔 주세요.');saveTimer=clock}}
 }
 if(keys.has('q'))cameraAngle-=dt*.7;if(keys.has('r'))cameraAngle+=dt*.7
}
let labelEls=new Map();function label(id,text,x,y,z,cls=''){let el=labelEls.get(id);if(!el){el=document.createElement('div');el.className='world-label '+cls;$('labels').append(el);labelEls.set(id,el)}el.textContent=text;let p=renderer.project(x,y,z);el.style.left=p.x+'px';el.style.top=p.y+'px';el.hidden=p.x<0||p.y<0||p.x>canvas.clientWidth||p.y>canvas.clientHeight;return el}
function updateLabels(){let ids=new Set();for(let s of layout.shelves){let id='s-'+s.code;ids.add(id);label(id,`${s.code} ${CATEGORIES[s.category]}`,s.x,2.96,s.z)}for(let n of state.npcs){if(n.mode==='phone'||n.arrival>state.elapsed||n.status==='gone')continue;let id=n.id;ids.add(id);let left=unresolved(n)&&n.deadline!=null?` · ${Math.ceil(secondsLeft(state,n))}초`:'';let t=n.status==='searching'?n.name+' · 책 찾는 중':n.guiding?n.name+' · 따라가는 중'+left:n.status==='asking'?'? '+n.name+left:n.status==='waiting'?n.name+' · 대기'+left:n.name+left;label(id,t,n.x,2.0,n.z,'npc-label')}label('player','사서 · 나',state.player.x,2,state.player.z);ids.add('player');for(let b of state.floor){ids.add(b.id);label(b.id,`▱ ${b.code}`,b.x,.22,b.z,'book-label')}label('board','운영시간 · 행사 게시판',layout.board.x,3.2,layout.board.z);ids.add('board');label('kiosk','무인 대출반납기',layout.kiosk.x,2.2,layout.kiosk.z);ids.add('kiosk');let phone=activeRequests(state).find(n=>n.mode==='phone');if(phone){label('phone',`☎ ${Math.ceil(secondsLeft(state,phone))}초`,layout.phone.x,1.9,layout.phone.z,'npc-label');ids.add('phone')}for(let[id,el]of labelEls)if(!ids.has(id)){el.remove();labelEls.delete(id)}}
function character(n,tint=[1,1,1]){let active=n.status==='searching'||(n===state.player?(keys.size>0||targetPath.length>0):n.path?.length>0);return {asset:assets.librarian,matrix:pose(n.x,0,n.z,n.angle),tint,animate:(node,local)=>{if(!active)return local;let name=node.name,sign=name.endsWith('L')?1:-1;if(name.startsWith('leg.')||name.startsWith('arm.')){let a=n.status==='searching'?(name.startsWith('arm')?-.7+Math.sin(n.walk)*.25:0):Math.sin(n.walk)*.32*sign*(name.startsWith('arm')?-1:1);return mul(local,transform([0,0,0],[Math.sin(a/2),0,0,Math.cos(a/2)]))}return local}}}
function instances(){let result=[{asset:assets.library,matrix:pose(0,0,0)},character(state.player),{asset:assets.cart,matrix:pose(state.cart.x,0,state.cart.z,state.cart.angle)},{asset:assets.phone,matrix:pose(layout.phone.x,1.29,layout.phone.z)},{asset:assets.kiosk,matrix:pose(layout.kiosk.x,0,layout.kiosk.z)},{asset:assets.board,matrix:pose(layout.board.x,1.9,layout.board.z,Math.PI/2)}];let addBook=(b,x,y,z,a=0)=>{let hex=COLORS[b.category];let color=[1,3,5].map(i=>Math.pow(parseInt(hex.slice(i,i+2),16)/255,2.2));result.push({asset:assets.book,matrix:pose(x,y,z,a),bookColor:[...color,1]})};
 for(let b of state.floor)addBook(b,b.x,.01,b.z,parseInt(b.id.replace(/\D/g,''))*1.3);
 state.cart.books.forEach((b,i)=>{let ox=(i%3-1)*.33,oy=i<6?1.10:.42,oz=(Math.floor(i/3)%2-.5)*.33,c=Math.cos(state.cart.angle),s=Math.sin(state.cart.angle);addBook(b,state.cart.x+ox*c+oz*s,oy,state.cart.z-ox*s+oz*c,state.cart.angle)});
 state.hands.forEach((b,i)=>addBook(b,state.player.x+Math.sin(state.player.angle)*.43,.71+i*.075,state.player.z+Math.cos(state.player.angle)*.43,state.player.angle));
 state.display.forEach((b,i)=>addBook(b,-9.05+i*.6,1.20,3.45,0));
 for(let n of state.npcs)if(n.mode!=='phone'&&n.status!=='gone'&&n.arrival<=state.elapsed)result.push(character(n,[[1.55,.95,.9],[.9,1.15,1.7],[1.6,1.3,.7],[1.15,.9,1.4]][n.roamIndex%4]));return result
}
function tick(now){let rawDt=lastTime?Math.max(0,(now-lastTime)/1000):0,dt=Math.min(rawDt,.05);lastTime=now;clock+=rawDt;let stopped=modal.open&&['help','review','morning','reset'].includes(modalContext),running=state&&!paused&&!document.hidden&&!state.ended&&!state.shiftClosed&&!state.morningPending&&!stopped;if(running){state.elapsed=Math.min(SHIFT_SECONDS,state.elapsed+rawDt);if(!modal.open)updatePlayer(dt);let born=advanceArrivals(state);if(born&&born.kind!=='roam')born.book=makeBook(born.id,born.category);updateNpcs(dt);let expired=expireRequests(state);if(expired.length){if(modalNpc&&expired.some(c=>c.id===modalNpc+'-complaint'))close();audio.failure();say(`${expired.length}건의 문의 시간이 끝났어요. 내일 민원으로 돌아옵니다.`);save();renderUI()}if(state.elapsed>=SHIFT_SECONDS)finishDay();if(clock-saveTimer>4){saveTimer=clock;save()}uiTimer+=rawDt;if(uiTimer>.4){uiTimer=0;renderUI()}}
 if(state){audio.update(!!running,activeRequests(state).some(n=>n.mode==='phone'&&!n.answered));let countdown=$('service-timer'),n=state.npcs.find(n=>n.id===modalNpc);if(countdown&&n){countdown.textContent=paused?'일시정지':`${Math.ceil(secondsLeft(state,n))}초`;countdown.classList.toggle('urgent',secondsLeft(state,n)<10)}let target=follow?[state.player.x,.3,state.player.z]:[0,.3,0];cameraTarget=cameraTarget.map((v,i)=>v+(target[i]-v)*Math.min(dt*4,1));let eye=[cameraTarget[0]+Math.sin(cameraAngle)*28,cameraTarget[1]+25,cameraTarget[2]+Math.cos(cameraAngle)*28],aspect=canvas.clientWidth/canvas.clientHeight,effectiveZoom=follow?zoom:Math.max(zoom,32/aspect);renderer.render(instances(),eye,cameraTarget,effectiveZoom);updateLabels();nearby=nearest();$('prompt').hidden=!nearby||paused||modal.open||state.ended;if(nearby)$('prompt').innerHTML=`<kbd>E</kbd> ${escape(nearby.label)}`;if(toastTimer>0){toastTimer-=rawDt;if(toastTimer<=0)$('toast').classList.remove('show')}}requestAnimationFrame(tick)}
window.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT')return;let k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();if(k==='p'&&!e.repeat){pause();return}if(modal.open){if(k==='Escape'&&userStarted&&!['review','morning'].includes(modalContext))close();return}if(['w','a','s','d','q','r','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(k))keys.add(k);if(e.repeat)return;if(k==='e')interact();if(k==='f'&&!paused&&!state.ended)phoneMenu();if(k==='c'&&!paused&&!state.ended)toggleCart();if(k==='i')inventoryMenu();if(k==='h')help();if(k==='Escape')pause()});window.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden&&state)save();lastTime=performance.now()});window.addEventListener('beforeunload',()=>{if(state)save()});
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{canvas.focus();drag={button:e.button,x:e.clientX,y:e.clientY,ox:e.clientX,oy:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(drag&&drag.button===2){cameraAngle+=(e.clientX-drag.x)*.008;drag.x=e.clientX;drag.y=e.clientY}});canvas.addEventListener('pointerup',e=>{if(drag&&drag.button===0&&Math.hypot(e.clientX-drag.ox,e.clientY-drag.oy)<6&&!modal.open&&!paused&&state){let dest=renderer.ground(e.clientX,e.clientY);targetPath=pathfind(state.player,dest,layout.colliders);if(!targetPath.length)say('그 위치로 이동할 수 없어요. 가까운 통로를 클릭해 주세요.')}drag=null});canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(9,Math.min(34,zoom+e.deltaY*.012))},{passive:false});
$('close-modal').onclick=close;modal.addEventListener('cancel',e=>{e.preventDefault();if(!['morning','review'].includes(modalContext)&&userStarted)close()});$('help-btn').onclick=help;$('pause-btn').onclick=pause;$('finish-day').onclick=finishDay;$('phone-btn').onclick=()=>{if(!paused&&!state.ended)phoneMenu()};$('overview-btn').onclick=()=>{follow=false;zoom=26;cameraAngle=.68};$('follow-btn').onclick=()=>{follow=true;zoom=13};$('reset-btn').onclick=()=>open('근무 기록을 초기화할까요?','저장된 진행 상황을 지우고 1일차부터 다시 시작합니다.',[{label:'1일차부터 다시 시작',run:()=>{state=newState();populateDay();close();paused=false;state.ended=false;$('pause-btn').textContent='일시정지';showMorning()}},{label:'계속 근무하기',primary:true,run:close}],'기록 초기화','reset');$('music-btn').onclick=()=>{audio.start();audio.enabled=!audio.enabled;$('music-btn').textContent=audio.enabled?'음악 ON':'음악 OFF'};$('fx-btn').onclick=()=>{audio.start();audio.fx=!audio.fx;$('fx-btn').textContent=audio.fx?'효과음 ON':'효과음 OFF'};document.addEventListener('pointerdown',()=>audio.start(),{capture:true});document.addEventListener('keydown',()=>audio.start(),{capture:true});$('mobile-e').onclick=interact;for(let b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(b.dataset.move);b.setPointerCapture(e.pointerId)});b.addEventListener('pointerup',()=>keys.delete(b.dataset.move));b.addEventListener('pointercancel',()=>keys.delete(b.dataset.move))}
async function init(){try{renderer=new Renderer(canvas);let names=['library','librarian','cart','book','phone','kiosk','board'],loaded=await Promise.all(names.map(n=>renderer.load(`assets/${n}.glb`)));assets=Object.fromEntries(names.map((n,i)=>[n,loaded[i]]));let response=await assetFetch('assets/layout.json');if(!response.ok)throw Error('도서관 배치 로드 실패');layout=await response.json();let restored=safeLoad();if(!restored){state=newState();populateDay()}renderUI();$('loading').remove();requestAnimationFrame(tick);if(!restored)help();else{userStarted=true;if(state.ended)showEnding(state.fired);else if(state.morningPending)showMorning();else if(state.shiftClosed)finishDay();else say('저장된 근무를 이어갑니다.')}window.libraryGame={get state(){return state},get layout(){return layout},get renderer(){return renderer},get nearby(){return nearby},get assets(){return assets},interact,computerMenu,machineMenu,talk,finishDay,inventoryMenu,close,renderUI,save,populateDay,toggleCart,getSelected,phoneMenu,noticeBoardMenu,guideShelfMenu,showMorning,get path(){return targetPath},goTo:(x,z)=>targetPath=pathfind(state.player,{x,z},layout.colliders)};
}catch(e){console.error(e);$('loading-text').textContent=e.message;$('loading').insertAdjacentHTML('beforeend','<p>README의 실행 방법을 확인해 주세요. HTML 파일을 직접 열면 모델을 불러올 수 없습니다.</p>')}}
